import ast

def has_valid_docstring(func_str: str) -> bool:
    try:
        tree = ast.parse(func_str)
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                return ast.get_docstring(node) is not None
        return False
    except SyntaxError:
        lines = [l.strip() for l in func_str.splitlines() if l.strip()]
        if len(lines) < 2: return False
        body = "\n".join(lines[1:])
        return (body.startswith('"""') and '"""' in body[3:]) or (body.startswith("'''") and "'''" in body[3:])

