def parse_env_file(raw_env: str) -> dict:
    config = {}
    for line in raw_env.splitlines():
        line = line.strip()
        if not line or line.startswith('#'): continue
        if '=' in line:
            k, v = line.split('=', 1)
            k, v = k.strip(), v.strip()
            if v.lower() == 'true': config[k] = True
            elif v.lower() == 'false': config[k] = False
            elif v.isdigit(): config[k] = int(v)
            else: config[k] = v.strip('"\'')
    return config

