class DBPool:
    def __init__(self, max_conns=2):
        self.max_conns = max_conns
        self.active = 0
    def acquire(self):
        if self.active >= self.max_conns:
            raise PoolExhaustedError('All DB connections active')
        self.active += 1
        return f'Conn-{self.active}'
    def release(self):
        self.active = max(0, self.active - 1)

