def moving_average(prices: list[float], k: int) -> list[float]:
    if len(prices) < k:
        return []
    window_sum = sum(prices[:k])
    averages = [round(window_sum / k, 2)]
    for i in range(k, len(prices)):
        window_sum += prices[i] - prices[i - k]
        averages.append(round(window_sum / k, 2))
    return averages

