import time

class TTLCache:
    def __init__(self):
        self.store = {}
    def set(self, key, value, ttl: float):
        expire_at = time.time() + ttl
        self.store[key] = (value, expire_at)
    def get(self, key):
        if key not in self.store:
            return None
        val, expire_at = self.store[key]
        if time.time() > expire_at:
            del self.store[key]  # Lazy eviction
            return None
        return val

c = TTLCache()
c.set('user_session', {'id': 42}, ttl=0.05)
print('Immediate get:', c.get('user_session'))
time.sleep(0.06)
print('Expired get:', c.get('user_session'))

import time

class TTLCache:
    def __init__(self):
        self.store = {}
    def set(self, key, value, ttl: float):
        # time.monotonic() guarantees steady progression without NTP clock jumps
        expire_at = time.monotonic() + ttl
        self.store[key] = (value, expire_at)
    def get(self, key):
        if key not in self.store:
            return None
        val, expire_at = self.store[key]
        if time.monotonic() > expire_at:
            del self.store[key]  # Lazy eviction
            return None
        return val

c = TTLCache()
c.set('user_session', {'id': 42}, ttl=0.05)
